import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o as t,af as s}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"LangChain：Agent Harness 的解剖学","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/agent/langchain-agent-harness.md","filePath":"zh/tech/agent/langchain-agent-harness.md","lastUpdated":1780925383000}'),r={name:"zh/tech/agent/langchain-agent-harness.md"};function o(i,a,l,h,d,g){return t(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="langchain-agent-harness-的解剖学" tabindex="-1">LangChain：Agent Harness 的解剖学 <a class="header-anchor" href="#langchain-agent-harness-的解剖学" aria-label="Permalink to &quot;LangChain：Agent Harness 的解剖学&quot;">​</a></h1><blockquote><p>来源：<a href="https://blog.langchain.com/the-anatomy-of-an-agent-harness/" target="_blank" rel="noreferrer">The Anatomy of an Agent Harness</a>，作者 Vivek Trivedi</p></blockquote><h2 id="核心定义" tabindex="-1">核心定义 <a class="header-anchor" href="#核心定义" aria-label="Permalink to &quot;核心定义&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent = Model + Harness</span></span>
<span class="line"><span>如果你不是模型，那你就是 Harness</span></span></code></pre></div><p><strong>Harness</strong> 是模型以外的所有代码、配置和执行逻辑。Raw 模型不是 Agent，只有通过 Harness 赋予状态、工具执行、反馈循环和可执行约束后，它才成为 Agent。</p><hr><h2 id="为什么需要-harness-从模型视角" tabindex="-1">为什么需要 Harness（从模型视角） <a class="header-anchor" href="#为什么需要-harness-从模型视角" aria-label="Permalink to &quot;为什么需要 Harness（从模型视角）&quot;">​</a></h2><p>模型本身只能接收数据（文本、图片、音频、视频）并输出文本，无法：</p><ul><li>跨交互维护持久状态</li><li>执行代码</li><li>访问实时知识</li><li>搭建环境完成工作</li></ul><p>这些都是 Harness 层要解决的问题。</p><hr><h2 id="harness-核心组件" tabindex="-1">Harness 核心组件 <a class="header-anchor" href="#harness-核心组件" aria-label="Permalink to &quot;Harness 核心组件&quot;">​</a></h2><h3 id="_1-文件系统-持久化存储和上下文管理" tabindex="-1">1. 文件系统：持久化存储和上下文管理 <a class="header-anchor" href="#_1-文件系统-持久化存储和上下文管理" aria-label="Permalink to &quot;1. 文件系统：持久化存储和上下文管理&quot;">​</a></h3><p>模型只能操作上下文窗口内的知识。Harness 通过文件系统抽象解决这个问题：</p><ul><li><strong>工作区</strong>：Agent 读取数据、代码、文档</li><li><strong>状态持久化</strong>：存储中间结果，跨 session 保持状态</li><li><strong>协作接口</strong>：多个 Agent 和人类通过共享文件协调</li></ul><p>Git 为文件系统增加了版本控制，支持跟踪工作、回滚错误、分支实验。</p><h3 id="_2-bash-code-作为通用工具" tabindex="-1">2. Bash + Code 作为通用工具 <a class="header-anchor" href="#_2-bash-code-作为通用工具" aria-label="Permalink to &quot;2. Bash + Code 作为通用工具&quot;">​</a></h3><p>更好的方案：给 Agent 一个通用工具如 <code>bash</code>，让它自主解决问题，而不是为每个操作预配置工具。</p><p>Bash + 代码执行 ≈ 给模型一台电脑，让它自己想办法。这让 Agent 可以动态设计自己的工具，而不是被固定工具集约束。</p><h3 id="_3-沙箱-执行和验证工作" tabindex="-1">3. 沙箱：执行和验证工作 <a class="header-anchor" href="#_3-沙箱-执行和验证工作" aria-label="Permalink to &quot;3. 沙箱：执行和验证工作&quot;">​</a></h3><p>本地执行 Agent 生成的代码有风险，单一环境也无法scale。</p><p>Harness 应连接到沙箱来运行代码、检查文件、安装依赖。沙箱还解锁了 scale：环境按需创建，分配到多个任务，完成后销毁。</p><p>好的环境还预装语言运行时、CLI 工具（git、测试框架）、浏览器等。</p><h3 id="_4-内存与搜索-持续学习" tabindex="-1">4. 内存与搜索：持续学习 <a class="header-anchor" href="#_4-内存与搜索-持续学习" aria-label="Permalink to &quot;4. 内存与搜索：持续学习&quot;">​</a></h3><p><strong>Filesystem 再次成为核心原语</strong>。Harness 支持 <code>AGENTS.md</code> 内存文件标准，在 Agent 启动时注入上下文。Agent 可以编辑这个文件，下个 session 继续使用。</p><p>对于知识截止日期后的新信息，用 Web Search 和 MCP 工具（如 Context7）来获取最新库版本或实时数据。</p><h3 id="_5-对抗-context-rot" tabindex="-1">5. 对抗 Context Rot <a class="header-anchor" href="#_5-对抗-context-rot" aria-label="Permalink to &quot;5. 对抗 Context Rot&quot;">​</a></h3><p><a href="https://research.trychroma.com/context-rot" target="_blank" rel="noreferrer">Context Rot</a> 描述模型在上下文窗口填满后性能下降的现象。</p><table tabindex="0"><thead><tr><th>问题</th><th>Harness 解决方案</th></tr></thead><tbody><tr><td>上下文快满</td><td><strong>Compaction</strong>：智能卸载和摘要上下文</td></tr><tr><td>大 Tool 输出</td><td><strong>Tool Call Offloading</strong>：保留首尾 token，中间存文件系统</td></tr><tr><td>太多工具/MCP 塞满上下文</td><td><strong>Skills</strong>：渐进式披露，需要时才加载</td></tr></tbody></table><h3 id="_6-长期自主执行" tabindex="-1">6. 长期自主执行 <a class="header-anchor" href="#_6-长期自主执行" aria-label="Permalink to &quot;6. 长期自主执行&quot;">​</a></h3><p>Long-horizon 工作需要：持久状态、规划、观察、验证。</p><ul><li><strong>Filesystem + Git</strong>：跨 session 跟踪工作</li><li><strong>Ralph Loops</strong>：拦截模型的退出尝试，重新注入原提示，迫使其继续工作</li><li><strong>Planning + Self-verification</strong>：模型分解目标，完成每步后自我验证</li></ul><hr><h2 id="model-training-和-harness-design-的耦合" tabindex="-1">Model Training 和 Harness Design 的耦合 <a class="header-anchor" href="#model-training-和-harness-design-的耦合" aria-label="Permalink to &quot;Model Training 和 Harness Design 的耦合&quot;">​</a></h2><p>今天的 Agent 产品（如 Claude Code、Codex）在训练时就把模型和 Harness 放在循环里。这创造了反馈循环：发现有用的原语 → 加入 Harness → 训练下一代模型时使用。</p><p>但这也带来泛化问题。<strong>改变工具逻辑会导致模型性能下降</strong>。比如 Codex-5.3 的 <code>apply_patch</code> 工具逻辑变更。</p><p>这也意味着：<strong>针对特定任务优化的 Harness 可能比模型原生的 Harness 效果更好</strong>。Terminal Bench 2.0 上，同一模型 Opus 4.6 在不同 Harness 中排名差异巨大。</p><hr><h2 id="harness-engineering-的未来方向" tabindex="-1">Harness Engineering 的未来方向 <a class="header-anchor" href="#harness-engineering-的未来方向" aria-label="Permalink to &quot;Harness Engineering 的未来方向&quot;">​</a></h2><ol><li>协调数百个 Agent 并行工作于共享代码库</li><li>Agent 分析自己的 traces 来识别和修复 Harness 级别的失败模式</li><li>Harness 动态组装正确的工具和上下文（JIT），而不是预配置</li></ol><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><blockquote><p><strong>模型包含智能，Harness 是让智能变得有用的系统。</strong></p></blockquote><p>Harness Engineering 是一个非常活跃的研究领域。它不仅仅是在修补模型缺陷，而是围绕模型智能构建系统，使其更有效。无论基础模型智能如何，配置良好的环境、正确的工具、持久状态和验证循环都能让任何模型更高效。</p>`,44)])])}const _=e(r,[["render",o]]);export{m as __pageData,_ as default};
